function handleLogo(e) {
  const file = e.target.files[0]; if (!file) return;
  const r = new FileReader();
  r.onload = ev => {
    logoBase64 = ev.target.result;
    document.getElementById('logoPreview').src = logoBase64;
    document.getElementById('logoPreview').classList.remove('d-none');
    document.getElementById('logoPlaceholder').classList.add('d-none');
    document.getElementById('removeLogo').classList.remove('d-none');
  };
  r.readAsDataURL(file);
}
function removeLogo() {
  logoBase64=''; document.getElementById('logoPreview').src='';
  document.getElementById('logoPreview').classList.add('d-none');
  document.getElementById('logoPlaceholder').classList.remove('d-none');
  document.getElementById('removeLogo').classList.add('d-none');
  document.getElementById('logoInput').value='';
}
