function openPreview() {
  const d=collectData(); if(!validate(d)) return;
  const preview = document.getElementById('invoicePreview');
  preview.innerHTML=`<div style="padding:40px;width:680px;box-sizing:border-box;font-family:'Segoe UI',sans-serif;font-size:14px;background:#fff;">${buildPreviewHTML(d)}</div>`;
  const modal = new bootstrap.Modal(document.getElementById('previewModal'));
  modal.show();
  // Pas hapjes së modalit, zbato scale në mobile (me siguri shtesë me setTimeout)
  const previewModalEl = document.getElementById('previewModal');
  previewModalEl.addEventListener('shown.bs.modal', applyMobilePreviewScale, { once: true });
  setTimeout(applyMobilePreviewScale, 150);
  setTimeout(applyMobilePreviewScale, 400);
}

function applyMobilePreviewScale() {
  const wrapper = document.getElementById('previewScrollWrapper');
  const preview = document.getElementById('invoicePreview');
  const inner = preview.firstElementChild;
  if (!inner) return;
  if (window.innerWidth >= 768) {
    inner.style.transform = '';
    preview.style.height = '';
    return;
  }
  const wrapperW = wrapper.clientWidth || window.innerWidth;
  const contentW = 680; // gjerësia fikse e brendshme e faturës (si në PC)
  const scale = Math.min(1, wrapperW / contentW);
  inner.style.width = contentW + 'px';
  inner.style.transformOrigin = 'top left';
  inner.style.transform = `scale(${scale})`;
  preview.style.height = (inner.scrollHeight * scale) + 'px';
}

// Zbato edhe për arkiva modal (mund të thirret disa herë në siguri; është idempotente)
function forceArkivaScale() {
  const wrapper = document.getElementById('arkivaScrollWrapper');
  const content = document.getElementById('arkivaPreviewContent');
  const inner = content.firstElementChild;
  if (!inner) return;
  if (window.innerWidth >= 768) {
    inner.style.transform = '';
    content.style.height = '';
    return;
  }
  const wrapperW = wrapper.clientWidth || window.innerWidth;
  const contentW = 680; // gjerësia fikse e brendshme e faturës (si në PC)
  const scale = Math.min(1, wrapperW / contentW);
  inner.style.width = contentW + 'px';
  inner.style.transformOrigin = 'top left';
  inner.style.transform = `scale(${scale})`;
  content.style.height = (inner.scrollHeight * scale) + 'px';
}
// Alias për pajtueshmëri me kodin e mëparshëm
const applyMobileArkivaScale = forceArkivaScale;

// Rillogarit shkallëzimin nëse ekrani ndryshon madhësi/rrotullohet ndërsa modali është i hapur
window.addEventListener('resize', () => {
  const previewModalEl = document.getElementById('previewModal');
  const arkivaModalEl = document.getElementById('viewArkivaModal');
  if (previewModalEl.classList.contains('show')) applyMobilePreviewScale();
  if (arkivaModalEl.classList.contains('show')) applyMobileArkivaScale();
});
window.addEventListener('orientationchange', () => {
  setTimeout(() => {
    const previewModalEl = document.getElementById('previewModal');
    const arkivaModalEl = document.getElementById('viewArkivaModal');
    if (previewModalEl.classList.contains('show')) applyMobilePreviewScale();
    if (arkivaModalEl.classList.contains('show')) applyMobileArkivaScale();
  }, 200);
});

function printInvoice() {
  const content=document.getElementById('invoicePreview').innerHTML;
  const win=window.open('','_blank','width=900,height=700');
  win.document.write(`<!DOCTYPE html><html><head><meta charset="UTF-8"><style>
    *{box-sizing:border-box;margin:0;padding:0}
    body{font-family:'Segoe UI',Arial,sans-serif;padding:30px;color:#111827;font-size:14px}
    table{width:100%;border-collapse:collapse}
    th,td{padding:8px 12px}
    th{background:#1e3a5f;color:#fff;font-size:0.8rem}
    td{border-bottom:1px solid #e5e7eb;font-size:0.88rem}
    tr:nth-child(even) td{background:#f8fafc}
    img{max-width:100%;height:auto}
    @media print{
      body{padding:10px}
      @page{margin:15mm;size:A4}
      a{text-decoration:none;color:inherit}
    }
  </style></head><body>${content}</body></html>`);
  win.document.close(); win.focus(); setTimeout(()=>{win.print();win.close();},600);
}

async function downloadPDF() { const d=collectData(); if(!validate(d)) return; await generatePDF(d); }
async function downloadPDFFromData(d) { if(!d) return; await generatePDF(d); }

async function generatePDF(d) {
  const {jsPDF} = window.jspdf;
  const filename = (d.isFature ? 'Fatura-' : 'Preventiv-') + d.nr_fatura + '.pdf';

  // Build a hidden render container with the invoice HTML
  const container = document.createElement('div');
  container.style.cssText = 'position:fixed;left:-9999px;top:0;width:794px;background:#fff;font-family:Segoe UI,Arial,sans-serif;font-size:14px;color:#111827;padding:40px;box-sizing:border-box;';
  container.innerHTML = buildPreviewHTML(d);
  document.body.appendChild(container);

  // Wait for images to load
  const imgs = container.querySelectorAll('img');
  await Promise.all(Array.from(imgs).map(img => new Promise(res => {
    if (img.complete) res(); else { img.onload = res; img.onerror = res; }
  })));

  // Lidhjet (Instagram, WhatsApp) -> zona klikuese në PDF
  const cRect = container.getBoundingClientRect();
  const mmPerPx = 210 / cRect.width;
  const pdfLinks = Array.from(container.querySelectorAll('a[href]')).map(a => {
    const r = a.getBoundingClientRect();
    return { url: a.href, x: (r.left - cRect.left) * mmPerPx, y: (r.top - cRect.top) * mmPerPx, w: r.width * mmPerPx, h: r.height * mmPerPx };
  });

  // Render to canvas
  const canvas = await html2canvas(container, {
    scale: 2,
    useCORS: true,
    backgroundColor: '#ffffff',
    width: 794,
    windowWidth: 794
  });
  document.body.removeChild(container);

  // A4 dimensions in mm
  const pageW = 210, pageH = 297;
  const imgW = pageW;
  const imgH = (canvas.height * pageW) / canvas.width;

  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });

  let posY = 0;
  let remaining = imgH;
  let page = 0;

  while (remaining > 0) {
    if (page > 0) doc.addPage();
    const sliceH = Math.min(pageH, remaining);
    // Crop canvas slice for this page
    const srcY = (page * pageH * canvas.width) / pageW;
    const srcH = (sliceH * canvas.width) / pageW;
    const sliceCanvas = document.createElement('canvas');
    sliceCanvas.width = canvas.width;
    sliceCanvas.height = srcH;
    sliceCanvas.getContext('2d').drawImage(canvas, 0, srcY, canvas.width, srcH, 0, 0, canvas.width, srcH);
    const imgData = sliceCanvas.toDataURL('image/jpeg', 0.95);
    doc.addImage(imgData, 'JPEG', 0, 0, imgW, sliceH);
    pdfLinks.forEach(l => {
      if (l.y >= page * pageH && l.y + l.h <= (page + 1) * pageH) doc.link(l.x, l.y - page * pageH, l.w, l.h, { url: l.url });
    });
    remaining -= pageH;
    page++;
  }

  const blob = doc.output('blob');
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 3000);
}
